      "正答は2と4です。グルコース酸化酵素（GOx）法では、グルコースの酸化により過酸化水素が生じ、これを比色反応や電極での検出に利用するため、2は正しいです。また、指先に果汁などが付着していると、その中のグルコースも反応して血糖値が高く出ることがあるため、4も正しいです。1は、グルコース脱水素酵素（GDH）法の種類によってはマルトースが測定に影響することがあり、妨害とならないとはいえません。3は、GOxを用いる酵素比色法では可視領域の呈色を測定するのが一般的で、215 nmではありません。5は、酵素電極法では酵素自体の電位差変化ではなく、反応で生じた物質や電子移動に伴う電流などを検出します。"
