    "ピークフローメーターにより得られた測定値と測定時の症状を、喘息日記に記載してください。",
    "この吸入薬は咳が出なくなったら、吸入しなくても良いです。",
    "この吸入薬は咳がさらにひどくなった場合、追加で1日3回まで吸入しても良いです。"
