    "アシクロビルに比べて副作用が現れにくい。",
    "腎機能が低下した時には、投与間隔の延長あるいは減量を伴った投与間隔の延長の措置を行う。",
    "7日間服用することで痛みは消失するが水泡は消失することはない。"
