      "軽度アルツハイマー型認知症では、まずコリンエステラーゼ阻害薬が候補となる。ドネペジルは軽度から使用でき、1日1回投与で服薬管理が比較的しやすく、口腔内崩壊錠は水なしでも服用しやすいため、追加提案として適切と考えられる。ガランタミンも軽度〜中等度で使用できるが、1日2回投与で管理がやや煩雑になる。内用液も特別な必要性がない限り優先度は高くない。リバスチグミン貼付剤は嚥下困難時などに有用だが、貼付管理や皮膚症状への注意が必要。メマンチンは主に中等度〜高度で用いられるため、軽度例の初期提案としては適切とはいえない。"
