      "78歳男性。経営している会社の業務量が最近急増し、デスクワークが毎日続いたため、眼精疲労と肩こりを強く感じ、一般用医薬品を購入するため来局した。男性が所持していたお薬手帳により、服用中の薬を確認した。男性はパーキンソン病で以下の処方薬を服用していることが判明した。\n\n（処方）\nレボドパ錠 200 mg　1回4錠（1日12錠）\n1日3回　朝昼夕食後　30日分",
