      "学校校舎の老朽化のために一部（図工準備室）の建替えが行われた。建替えた校舎を利用した生徒から、目、鼻、のどの刺激、めまいの訴えが続いた。養護教諭から学校薬剤師に相談があり、学校薬剤師はこの教室内の空気中の化学物質検査を行うことにした。学校環境衛生基準に指定されている物質であり、生徒の症状の原因と考えられるもの（一酸化炭素、アセトン、ホルムアルデヒド、トルエン、アスベストの中から該当するもの）を測定するための学校環境衛生基準に基づいた測定法はどれか。2つ選べ。",

    choices: [
    "検知管法",
    "ザルツマン法",
    "ジニトロフェニルヒドラジン誘導体化法を用いた高速液体クロマトグラフ法",
    "ガスクロマトグラフ ― 質量分析法",
    "酵素免疫測定法"
    ],

    answer: [2, 3],


    explanation:
      "建替え後の教室で、目・鼻・のどの刺激やめまいが続く場合、いわゆるシックハウス（シックスクール）関連物質が疑われます。学校環境衛生基準で測定対象となる代表例はホルムアルデヒドとトルエンです。ホルムアルデヒドは、ジニトロフェニルヒドラジン（DNPH）誘導体化法を用いたHPLCで測定します。トルエンなどの揮発性有機化合物は、ガスクロマトグラフ―質量分析法（GC-MS）で測定します。したがって3、4が正答です。1の検知管法は一酸化炭素などの測定に用いられますが、今回の新築・改築後の刺激症状の原因物質としての中心ではありません。2のザルツマン法は二酸化窒素の測定法です。5の酵素免疫測定法は本問の学校環境衛生基準に基づく測定法としては該当しません。"
