    question:
      "42歳女性。5年前に出産後、しばしば複視が出現した。他の症状は認められなかったが、2年経過後、眼瞼下垂、四肢の疲労感が出現し始めた。半年前からは、夕方になると増悪し、台所仕事ができない、しゃべりにくいなどの症状が出現したため、近医を受診した。血液検査で抗アセチルコリン受容体抗体の値が23 nmol/L（正常値0.0－0.2 nmol/L）であり、重症筋無力症と診断され、治療開始となった。\n\n（処方）\nピリドスチグミン臭化物錠60 mg 1回1錠（1日2錠）\n1日2回 朝夕食後 3日分\n\nピリドスチグミン臭化物錠60 mgの内服を開始後、3日目の早朝から体調不良を訴え、救急外来を受診した。医師は投与量の妥当性を確認するために、注射剤としてエドロホニウム塩化物2 mgを投与したところ、発汗、腹痛などの症状が増悪した。\n\nこの患者に対する治療処置により、患者の症状は緩和された。この症状が緩和される機序はどれか。2つ選べ。",

