    field: "薬理",

    question:
      "75歳男性。7年前にパーキンソン病と診断され、レボドパ・ベンセラジド塩酸塩配合錠の投与によって日常生活は問題のないレベルを維持してきた。胃がんの手術のため外科病棟に入院したところ、この配合錠を正しく服用しているにもかかわらず、症状の日内変動（wearing-off現象）が認められるようになった。外科の主治医から病棟担当薬剤師に、wearing-offの治療に関する相談があり、一剤追加することになった。この患者に対して、トリヘキシフェニジル塩酸塩、イストラデフィリン、ドロキシドパ、ビペリデン塩酸塩、エンタカポンの中から提案すべき併用薬物として適切なものの作用機序として正しいのはどれか。2つ選べ。",

    choices: [
    "線条体において、アデノシンA₂A受容体を遮断する。",
    "線条体において、ドパミンD₂受容体を遮断する。",
    "芳香族L-アミノ酸脱炭酸酵素によりノルアドレナリンに変換され、脳内のノルアドレナリンを補充する。",
    "主に末梢において、カテコール-O-メチルトランスフェラーゼ（COMT）を阻害し、レボドパの代謝を抑制する。",
    "線条体において、ムスカリン性アセチルコリン受容体を遮断する。"
    ],

    answer: [0, 3],


    explanation:
      "wearing-off現象は、レボドパの効果持続時間が短くなり、次回服用前に症状が悪化する状態です。対策として、レボドパ作用を延長する薬や、別機序で運動症状を改善する薬を併用します。\n\n1は正しいです。イストラデフィリンは線条体のアデノシンA₂A受容体を遮断し、wearing-off時の運動症状改善に用いられます。\n\n4も正しいです。エンタカポンは主に末梢でCOMTを阻害し、レボドパの代謝を抑えることで、脳内へ移行するレボドパ量を増やし効果を延長します。\n\n2のドパミンD₂受容体遮断は、むしろパーキンソン症状を悪化させる方向です。3はドロキシドパの作用ですが、すくみ足や起立性低血圧などで用いられ、wearing-off対策としての追加薬としては優先されません。5はトリヘキシフェニジルやビペリデンの作用で、振戦に用いられることがありますが、高齢者では抗コリン作用による副作用にも注意が必要で、wearing-off対策としては適切とはいえません。"
