    caseContext:
      "76歳男性。軽度の認知症、糖尿病、高血圧、うつ病のため、以下の処方薬を常用している。1年前から頻尿、残尿感及び排尿困難感があったが放置していた。風邪気味であったため、2日前に自宅の常備薬である市販の総合感冒薬を服用した。昨日の昼から尿がほとんど出なくなったため、かかりつけ薬剤師に相談に来た。\n\n（処方）\nカンデサルタン口腔内崩壊錠 4 mg　1回1錠（1日1錠）\nシタグリプチンリン酸塩水和物錠 50 mg　1回1錠（1日1錠）\n1日1回　朝食後　30日分\nイミプラミン塩酸塩錠 25 mg　1回3錠（1日6錠）\n1日2回　朝夕食後　30日分\nボグリボース錠 0.2 mg　1回1錠（1日3錠）\n1日3回　朝昼夕食直前　30日分\nリバスチグミン経皮吸収型製剤 18 mg　1回1枚（1日1枚）\n上腕部に貼布　30日分\n\nまた、総合感冒薬に含まれている成分は以下のとおりである。\nアセトアミノフェン\nd-クロルフェニラミンマレイン酸塩\nジヒドロコデインリン酸塩\ndl-メチルエフェドリン塩酸塩\n無水カフェイン",
