    question:
      "63歳男性。根治切除不能な悪性黒色腫と診断され、外来化学療法でニボルマブが投与されることになった。薬剤師が初回投与時に患者のもとを訪れ、抗がん薬の特徴や注意すべき副作用の説明を行うことになった。\n\nニボルマブの市販後に報告されている以下の副作用のうち、その作用機序から考えて、間接的に生じると思われる副作用として最も適切なのはどれか。1つ選べ。",

