    "この患者におけるメトホルミンの全身クリアランスは、約170 mL/min と予想されます。",
    "この患者におけるメトホルミンの尿中排泄率は、腎機能正常者の約1/3 と予想されます。",
    "処方どおりに服用し続けた場合、この患者におけるメトホルミンの平均血中濃度は腎機能正常者の約3倍になると予想されます。",
    "この患者が処方どおりに服用し続けた場合、メトホルミンの平均血中濃度は約10 μg/mL と予想されます。"
