      "36歳男性。10年前に双極性障害の診断を受け、処方1による治療を行っている。\n\n（処方1）\n炭酸リチウム錠200 mg　1回3錠（1日3錠）\n1日1回　就寝前　28日分\n\n患者は、10日前に腰痛により自宅近くの整形外科を受診し、処方2の薬剤の服用を開始した。\n\n（処方2）\nロキソプロフェンNa錠60 mg　1回1錠（1日3錠）\n1日3回　朝昼夕食後　14日分\n\n2日前より下痢や嘔吐が出現し、今朝、ふらつきと発語困難を生じたため、緊急搬送された。リチウムの血清中濃度は、2.2 mEq/L（血中濃度1.8 mEq/Lに相当）と測定された。薬剤師が残薬を確認したところ、指示どおりの服薬状況であった。",
