    question:
      "緊急搬送時でのこの患者におけるリチウムの全身クリアランス（L/hr）に最も近い値はどれか。1つ選べ。ただし、計算には血中濃度を用い、測定したリチウム濃度は定常状態における平均濃度であるものとする。また、リチウムのバイオアベイラビリティは100%とし、炭酸リチウム（Li2CO3）の分子量は73.9である。",

