      "70歳男性。切除不能な胃がんの治療のため、S-1（テガフール・ギメラシル・オテラシルカリウム配合剤）/シスプラチン療法を施行している。数日前から右下肢に痙れん様のふるえが認められている。精密検査の結果、左脳にがん転移が認められ、緊急入院となった。痙れん発作の予防としてフェニトインの服用を開始した。\n\n（処方）\nフェニトイン錠100 mg　1回1錠（1日3錠）\n1日3回　朝昼夕食後　7日分",
