    caseContext:
      "66歳男性。身長168 cm、体重51 kg。胃がんによる胃全摘術後に中心静脈栄養法を実施している。糖尿病の既往があり、血糖値上昇が見られたため、インスリンを投与することになった。輸液セットは感染予防のためフィルターを組み込んだ閉鎖回路としている。医師より「インスリン ヒト（遺伝子組換え）注射液100単位/mLを生理食塩液で希釈して50単位分調製し、投与する」よう指示があった。看護師から調製したインスリン注射液の投与法について質問があったため、薬剤師は、以下の模式図を書いて説明を行った。模式図には、輸液バッグ、輸液セット、A、輸液フィルター、B、患者へが示されている。",
