    hasImage: true,
    image: "/pharmacy/104/practical/q283.png",

    question:
      "66歳男性。身長168 cm、体重51 kg。胃がんによる胃全摘術後に中心静脈栄養法を実施している。糖尿病の既往があり、血糖値上昇が見られたため、インスリンを投与することになった。輸液セットは感染予防のためフィルターを組み込んだ閉鎖回路としている。医師より「インスリン ヒト（遺伝子組換え）注射液100単位/mLを生理食塩液で希釈して50単位分調製し、投与する」よう指示があった。看護師から調製したインスリン注射液の投与法について質問があったため、薬剤師は、以下の模式図を書いて説明を行った。\n\n模式図では、輸液バッグから患者へ向かう輸液セットに輸液フィルターが組み込まれており、Aは輸液フィルターより輸液バッグ側、Bは輸液フィルターより患者側の側管を示す。\n\n調製したインスリン注射液の投与法として最も適切な方法を、次の1〜5から選択する。\n1 輸液バッグ内液に添加して持続静注する。\n2 Aよりシリンジポンプで持続静注する。\n3 Aより急速静注する。\n4 Bよりシリンジポンプで持続静注する。\n5 Bより急速静注する。\n\nこの投与法を選択した理由に最も深く関係する事象はどれか。1つ選べ。",

