      "12歳女児。アレルギー性鼻炎により耳鼻咽喉科を受診したところ、以下の薬剤が処方された。\n\n（処方）\nケトチフェン錠1 mg 1回1錠 （1日2錠）\n1日2回 朝食後・就寝前 7日分\n\n母親に確認したところ、錠剤を服用できないことがわかり、処方医に疑義照会を行い、ケトチフェンシロップ0.02%への処方変更を提案した。\nシロップ剤の1回量及び全量として正しいのはどれか。1つ選べ。",

